def reverse_words(s: str) -> str:
    # BUG: should reverse the list of words, not each word
    return ' '.join(w[::-1] for w in s.split())


def count_vowels(s: str) -> int:
    # BUG: missing 'u' from vowel set
    return sum(1 for c in s.lower() if c in 'aeioy')


def is_palindrome(s: str) -> bool:
    # BUG: does not ignore case or spaces
    cleaned = s
    return cleaned == cleaned[::-1]

from src.strutils import reverse_words, count_vowels, is_palindrome


def test_reverse_words():
    assert reverse_words("hello world") == "world hello"
    assert reverse_words("one two three") == "three two one"


def test_count_vowels():
    assert count_vowels("hello") == 2
    assert count_vowels("aeiou") == 5


def test_is_palindrome_basic():
    assert is_palindrome("racecar")
    assert not is_palindrome("hello")


def test_is_palindrome_case():
    assert is_palindrome("Racecar")
    assert is_palindrome("A man a plan a canal Panama")


def test_count_vowels_uppercase():
    assert count_vowels("HELLO WORLD") == 3
